\centering
\small
\begin{tabular}{lccc}
\toprule
\textbf{Model} & \textbf{CR-comp.}$^a$ & \textbf{Thresh.}$^b$ & $p$ \textbf{(thresh.)} \\
\midrule
R1-8B & L0 (0\%) & L14 (44\%) & ${<}0.001$ \\
